using Microsoft.Xna.Framework;
namespace StarlightSyndicateDemo;
public sealed class ProbePreset{public string Name{get;set;}="Custom";public float Range{get;set;}=4;public List<ProbeOffset> Offsets{get;set;}=[];}
public sealed class ProbeOffset{public float X{get;set;}public float Y{get;set;}public float Z{get;set;}public float Range{get;set;}=4;}
public sealed class ProbeScanSample{public string Id{get;set;}="";public string Payload{get;set;}="ut_probe_core";public float X{get;set;}public float Y{get;set;}public float Z{get;set;}public float Range{get;set;}=4;}
public sealed class ProbeScanJob{public string System{get;set;}="";public float Duration{get;set;}public float StrengthMultiplier{get;set;}=1;public float DeviationMultiplier{get;set;}=1;public List<ProbeScanSample> Samples{get;set;}=[];}
public sealed partial class DemoWorld
{
 public string ProbeFormation="Pinpoint",ProbeStatus="Launch scan probes to begin.";public bool ProbeLayoutCustomized;public int ProbeScanPass;public ProbeScanJob? ProbeJob;public List<ProbePreset> ProbePresets=[];
 public int Astrometrics=1,AstrometricRangefinding,AstrometricPinpointing,AstrometricAcquisition;
 public IEnumerable<ScanProbe> ActiveScanProbes=>ScanProbes.Where(p=>p.System==SystemId&&p.Connected&&p.Enabled&&p.Recall<=0&&p.Life>0);
 public float ProbeMinRange=>ActiveScanProbes.Any(p=>p.Payload=="ut_probe_combat")?.5f:.25f;
 public float ProbeMaxRange=>ActiveScanProbes.Any()&&ActiveScanProbes.All(p=>p.Payload=="ut_probe_combat")?64:32;
 public float ScanStrengthMultiplier=>Player.UtilityFactor("probeStrength")*(1+.05f*Math.Clamp(Astrometrics,0,5))*(1+.05f*Math.Clamp(AstrometricRangefinding,0,5));
 public float ScanDeviationMultiplier=>Player.UtilityFactor("probeDeviation")*(1-.05f*Math.Clamp(Astrometrics,0,5))*(1-.05f*Math.Clamp(AstrometricPinpointing,0,5));
 public float ScanDuration=>Math.Max(1,10*Player.UtilityFactor("probeScanTime")*(1-.05f*Math.Clamp(Astrometrics,0,5))*(1-.05f*Math.Clamp(AstrometricAcquisition,0,5)));
 public float EffectiveProbeStrength=>(ActiveScanProbes.Any()&&ActiveScanProbes.All(p=>p.Payload=="ut_probe_combat")?20:40)*ScanStrengthMultiplier;
 static readonly Vector3[] PinpointOffsets=[new(-.28f,-.28f,-.28f),new(.28f,.28f,-.28f),new(.28f,-.28f,.28f),new(-.28f,.28f,.28f),new(.28f,-.28f,-.28f),new(-.28f,.28f,-.28f),new(-.28f,-.28f,.28f),new(.28f,.28f,.28f)];
 public static Vector3 ProbeActualAU(ScanProbe p)=>new(p.X/(float)SolarCatalog.AU,p.Y/(float)SolarCatalog.AU,p.Z/(float)SolarCatalog.AU);
 public static Vector3 ProbePlannedAU(ScanProbe p)=>p.Planned?new(p.PlanX,p.PlanY,p.PlanZ):ProbeActualAU(p);
 public void EnsureProbeCatalog(){EnsureExplorationF();EnsureRegionalSitesN();
  string[] kinds=["Data","Relic","Gas","Wormhole","Combat","Ore"];string[] names=["Abandoned Concord Data Vault","Silent Cartographer Archive","Glasswind Vapor Reservoir","Unstable Spatial Fracture","Syndicate Listening Post","Hidden Riftstone Deposit"];
  var planets=SolarCatalog.ForSystem(SystemId).Where(c=>c.Kind==CelestialKind.Planet).Take(3).ToArray();
  for(int i=0;i<kinds.Length;i++){string id=SystemId+"_sig_"+i;if(UtilitySites.Any(s=>s.Id==id))continue;Vector3 pos=planets.Length==0?new(i+1,.3f,-1):planets[i%planets.Length].Position.Local/(float)SolarCatalog.AU;pos+=new Vector3(.55f+i*.15f,i%2==0?.35f:-.45f,-.7f);UtilitySites.Add(new(){Id=id,System=SystemId,Kind=kinds[i],Name=names[i],Difficulty=i==1?3:i==4?4:1,X=pos.X,Y=pos.Y,Z=pos.Z,EstimateX=pos.X+1.2f,EstimateY=pos.Y+.3f,EstimateZ=pos.Z-.9f});}
  foreach(var celestial in SolarCatalog.ForSystem(SystemId).Where(c=>c.Kind==CelestialKind.Anomaly&&c.Id!="umbra:signal")){if(UtilitySites.Any(s=>s.Id==celestial.Id))continue;Vector3 pos=celestial.Anchor.Local/(float)SolarCatalog.AU;UtilitySites.Add(new(){Id=celestial.Id,System=SystemId,Kind="Combat",Name=celestial.Name,Anomaly=true,Seen=true,Signal=100,X=pos.X,Y=pos.Y,Z=pos.Z,EstimateX=pos.X,EstimateY=pos.Y,EstimateZ=pos.Z,ResultShape="Point"});}
  if(SystemId=="umbra"&&!UtilitySites.Any(s=>s.Id=="umbra:signal")){var c=SolarCatalog.ById["umbra:signal"];Vector3 pos=c.Anchor.Local/(float)SolarCatalog.AU;UtilitySites.Add(new(){Id=c.Id,System=SystemId,Kind="Data",Name="JoyOS Memory Vault",Difficulty=2,Signal=SignalResolved?100:0,Seen=SignalResolved,X=pos.X,Y=pos.Y,Z=pos.Z,EstimateX=pos.X+1,EstimateY=pos.Y,EstimateZ=pos.Z-1});}
  foreach(var site in UtilitySites.Where(s=>s.System==SystemId&&s.Name.Length==0))site.Name=site.Kind+" exploration site";
 }
 public void RefreshCombatProbeContacts(){
  var seen=new HashSet<string>();void Contact(SpaceTarget t,SpacePosition origin,string grid){if(!t.Alive||t.Kind is not(TargetKind.Raider or TargetKind.Station)||t.Profile?.Special.Any(s=>s.Active&&s.Definition?.Cloak==true)==true)return;string key=grid+"|"+t.Id;seen.Add(key);var s=UtilitySites.FirstOrDefault(s=>s.System==SystemId&&s.TargetId==t.Id&&s.ContactGrid==grid);var pos=(origin+SpacePosition.From(t.Position)).Local/(float)SolarCatalog.AU;if(s==null){s=new(){Id=SystemId+"_contact_"+UtilitySites.Count,System=SystemId,TargetId=t.Id,ContactGrid=grid,Kind=t.DroneId.Length>0?"Drone":t.Kind==TargetKind.Station?"Structure":"Ship",Name=t.Name,TargetName=t.Name,Difficulty=1};UtilitySites.Add(s);}s.X=pos.X;s.Y=pos.Y;s.Z=pos.Z;}
  foreach(var target in Targets)Contact(target,IsSolarGrid?SolarOrigin:default,"");
  foreach(var grid in SolarGrids.Where(g=>g.Key.StartsWith(SystemId+":")&&g.Key!=SolarGridKey))foreach(var target in grid.Value.Targets)Contact(target,grid.Value.Origin,grid.Key);
  foreach(var site in UtilitySites.Where(s=>s.System==SystemId&&s.TargetId.Length>0))if(!seen.Contains(site.ContactGrid+"|"+site.TargetId)){site.Signal=0;site.Seen=false;}
 }
 public void RefreshProbeResults(){EnsureProbeCatalog();RefreshCombatProbeContacts();}
 public void DeployProbeFormation(UtilityState state){int q=Math.Min(state.Loaded,Math.Max(0,8-ScanProbes.Count(p=>p.Connected&&p.System==SystemId&&p.Recall<=0)));var position=SystemPosition.Local/(float)SolarCatalog.AU;for(int i=0;i<q;i++)ScanProbes.Add(new(){Payload=state.PayloadId,System=SystemId,X=position.X*(float)SolarCatalog.AU,Y=position.Y*(float)SolarCatalog.AU,Z=position.Z*(float)SolarCatalog.AU});state.Loaded-=q;ProbeCenter=position;SetProbeFormation("Pinpoint");EnsureProbeCatalog();ProbeStatus=$"Launched {q} probes.";Say(ProbeStatus);if(state.Loaded==0&&ItemCount(state.PayloadId,false)>0){int refill=(int)Math.Min(8,ItemCount(state.PayloadId,false));ChangeStack(state.PayloadId,false,-(decimal)(refill));state.Loaded=refill;state.ReloadLeft=state.Definition!.Reload;}}
 public bool LaunchScanProbes(){if(InHubH){Say("Probes unavailable in this restricted hub.");return false;}if(Docked||Cloaked){Say("Undock and decloak before launching probes.");return false;}if(ScanProbes.Count(p=>p.System==SystemId&&p.Connected)>=8){Say("Eight probes are already controlled.");return false;}var state=Player.Utilities.FirstOrDefault(s=>s.Effective&&s.Definition?.Kind is "CoreProbe" or "CombatProbe");if(state==null){Say("Fit an online scan probe launcher.");return false;}int slot=Array.IndexOf(Player.Utilities,state);if(state.Active)return false;if(state.Loaded==0){string payload=state.PayloadId.Length>0?state.PayloadId:state.Definition!.Kind=="CombatProbe"?"ut_probe_combat":"ut_probe_core";if(!LoadUtilityPayload(slot,payload,false))return false;}if(state.ReloadLeft>0){Say("Probe launcher is reloading.");return false;}return ToggleUtility(slot);}
 public void SetProbeFormation(string formation){ProbeFormation=formation;ProbeLayoutCustomized=false;ProbeRange=Math.Clamp(formation=="Spread"?16:4,ProbeMinRange,ProbeMaxRange);PlanStandardFormation();}
 void PlanStandardFormation(){int i=0;foreach(var p in ActiveScanProbes){var offset=PinpointOffsets[i++%8]*ProbeRange*(ProbeFormation=="Spread"?2.6f:1);PlanProbe(p,ProbeCenter+offset,ProbeRange);} }
 public void PlanProbe(ScanProbe p,Vector3 position,float range){if(!float.IsFinite(position.X)||!float.IsFinite(position.Y)||!float.IsFinite(position.Z))return;p.PlanX=position.X;p.PlanY=position.Y;p.PlanZ=position.Z;p.PlanRange=Math.Clamp(range,p.Payload=="ut_probe_combat"?.5f:.25f,p.Payload=="ut_probe_combat"?64:32);p.Planned=true;}
 public void MoveProbeFormation(Vector3 center){if(!float.IsFinite(center.X)||!float.IsFinite(center.Y)||!float.IsFinite(center.Z))return;var delta=center-ProbeCenter;ProbeCenter=center;if(!ProbeLayoutCustomized){PlanStandardFormation();return;}foreach(var p in ActiveScanProbes)PlanProbe(p,ProbePlannedAU(p)+delta,p.PlanRange);}
 public void SetProbeRange(float range){if(!float.IsFinite(range))return;float target=Math.Clamp(MathF.Pow(2,MathF.Round(MathF.Log2(Math.Max(.25f,range)))),ProbeMinRange,ProbeMaxRange);float ratio=target/Math.Max(.25f,ProbeRange);ProbeRange=target;if(!ProbeLayoutCustomized){PlanStandardFormation();return;}foreach(var p in ActiveScanProbes)PlanProbe(p,ProbeCenter+(ProbePlannedAU(p)-ProbeCenter)*ratio,target);}
 public void ScaleProbeSpacing(float factor){if(!float.IsFinite(factor))return;factor=Math.Clamp(factor,.05f,20);foreach(var p in ActiveScanProbes)PlanProbe(p,ProbeCenter+(ProbePlannedAU(p)-ProbeCenter)*factor,p.PlanRange);ProbeLayoutCustomized=true;ProbeFormation="Custom";}
 public void MoveSingleProbe(string id,Vector3 position){var p=ActiveScanProbes.FirstOrDefault(p=>p.Id==id);if(p==null)return;PlanProbe(p,position,p.PlanRange);ProbeLayoutCustomized=true;ProbeFormation="Custom";}
 public void SaveProbePreset(string name){if(ActiveScanProbes.Count()!=8)return;name=string.IsNullOrWhiteSpace(name)?"Custom "+(ProbePresets.Count+1):name.Trim();ProbePresets.RemoveAll(p=>p.Name==name);ProbePresets.Add(new(){Name=name,Range=ProbeRange,Offsets=ActiveScanProbes.Select(p=>{var v=ProbePlannedAU(p)-ProbeCenter;return new ProbeOffset{X=v.X,Y=v.Y,Z=v.Z,Range=p.PlanRange};}).ToList()});}
 public bool LoadProbePreset(string name){var preset=ProbePresets.FirstOrDefault(p=>p.Name==name);if(preset==null||ActiveScanProbes.Count()!=8)return false;ProbeRange=preset.Range;ProbeFormation=name;ProbeLayoutCustomized=true;int i=0;foreach(var p in ActiveScanProbes){var o=preset.Offsets[i++];PlanProbe(p,ProbeCenter+new Vector3(o.X,o.Y,o.Z),o.Range);}return true;}
 public bool BeginProbeAnalysis(){if(InHubH){ProbeStatus="Analysis unavailable in restricted hub.";return false;}RefreshProbeResults();if(Docked||ProbeScanLeft>0||!ActiveScanProbes.Any()){ProbeStatus=Docked?"Undock before analyzing.":ProbeScanLeft>0?"Analysis already running.":"Launch or reconnect probes.";Say(ProbeStatus);return false;}if(!ProbeLayoutCustomized){ProbeRange=Math.Clamp(ProbeRange,ProbeMinRange,ProbeMaxRange);PlanStandardFormation();}var samples=ActiveScanProbes.Select(p=>{var v=ProbePlannedAU(p);p.X=v.X*(float)SolarCatalog.AU;p.Y=v.Y*(float)SolarCatalog.AU;p.Z=v.Z*(float)SolarCatalog.AU;p.RangeAU=p.PlanRange;return new ProbeScanSample{Id=p.Id,Payload=p.Payload,X=v.X,Y=v.Y,Z=v.Z,Range=p.PlanRange};}).ToList();ProbeJob=new(){System=SystemId,Duration=ScanDuration,StrengthMultiplier=ScanStrengthMultiplier,DeviationMultiplier=ScanDeviationMultiplier,Samples=samples};ProbeScanLeft=ProbeJob.Duration;ProbeStatus="Probes repositioning / analyzing";return true;}
 public void CancelProbeAnalysis(){ProbeJob=null;ProbeScanLeft=0;ProbeStatus="Analysis cancelled.";}
 public bool RecoverActiveProbes(string id=""){if(Docked)return false;bool any=false;foreach(var p in ScanProbes.Where(p=>p.System==SystemId&&p.Connected&&(id.Length==0||p.Id==id))){p.Recall=3;any=true;}if(any)CancelProbeAnalysis();return any;}
 public int ReconnectScanProbes(){if(Docked)return 0;int limit=8-ScanProbes.Count(p=>p.System==SystemId&&p.Connected);int count=0;foreach(var p in ScanProbes.Where(p=>p.System==SystemId&&!p.Connected&&p.Life>0).Take(Math.Max(0,limit))){p.Connected=true;p.Recall=0;count++;}ProbeStatus=$"Reconnected {count} probes.";return count;}
 public bool DestroyScanProbe(string id){var p=ScanProbes.FirstOrDefault(p=>p.Id==id&&p.System==SystemId);if(p==null)return false;ScanProbes.Remove(p);return true;}
 public void RecoverProbesForTransit(){CancelProbeAnalysis();foreach(var p in ScanProbes.Where(p=>p.System==SystemId&&p.Connected).ToArray())ReturnProbeToCargo(p);}
 void ReturnProbeToCargo(ScanProbe p){if(CargoUsed+ItemVolume(p.Payload)<=Player.CargoMax)ChangeStack(p.Payload,false,(decimal)(1));else Say("Cargo full: probe lost during recovery.");ScanProbes.Remove(p);}
 public void TickProbeScanning(float dt){if(dt<=0)return;foreach(var p in ScanProbes.ToArray()){p.Life-=dt;if(p.Life<=0){if(p.System==SystemId&&p.Connected)ReturnProbeToCargo(p);else ScanProbes.Remove(p);continue;}if(p.Recall>0&&p.System==SystemId){p.Recall=Math.Max(0,p.Recall-dt);if(p.Recall==0)ReturnProbeToCargo(p);}}
 if(ProbeScanLeft<=0||ProbeJob==null)return;ProbeScanLeft=Math.Max(0,ProbeScanLeft-dt);if(ProbeScanLeft>0)return;var job=ProbeJob;ProbeJob=null;if(job.System!=SystemId)return;RefreshCombatProbeContacts();ProbeScanPass++;RecordExperienceI("scan",1);foreach(var site in UtilitySites.Where(s=>s.System==SystemId&&!s.Anomaly)){site.PreviousSignal=site.Signal;var target=new Vector3(site.X,site.Y,site.Z);var hits=job.Samples.Where(p=>ScanProbes.Any(a=>a.Id==p.Id&&a.Connected&&a.Enabled&&a.Recall<=0)&&Vector3.Distance(new(p.X,p.Y,p.Z),target)<=p.Range&&(site.Kind is not("Ship" or "Drone" or "Structure" or "Trace")||p.Payload=="ut_probe_combat")).Select(p=>(Probe:p,Distance:Vector3.Distance(new(p.X,p.Y,p.Z),target))).OrderBy(h=>h.Distance/h.Probe.Range).ToArray();if(site.TargetId.Length>0&&!ProbeContactAlive(site))hits=[];site.HitCount=hits.Length;if(hits.Length==0){site.Signal=0;site.ResultShape="Sphere";continue;}site.Seen=true;float strength=hits.Take(4).Average(h=>(h.Probe.Payload=="ut_probe_combat"?20:40)*job.StrengthMultiplier*(h.Probe.Payload=="ut_probe_combat"?.5f:.25f)/h.Probe.Range);Vector3 coverageCenter=hits.Aggregate(Vector3.Zero,(v,h)=>v+new Vector3(h.Probe.X,h.Probe.Y,h.Probe.Z))/hits.Length;float coverage=Math.Clamp(1-Vector3.Distance(coverageCenter,target)/hits[0].Probe.Range*.8f,.05f,1);float geometry=ProbeGeometry(hits.Take(8).Select(h=>new Vector3(h.Probe.X,h.Probe.Y,h.Probe.Z)).ToArray(),hits[0].Probe.Range);float requirement=site.TargetId.Length>0?ProbeContactDifficulty(site):site.Difficulty switch{>=5=>104,4=>72,3=>42,2=>24,_=>12};float signal=100*strength/Math.Max(1,requirement)*coverage*geometry;if(hits.Length<4)signal=Math.Min(signal,new[]{0,24.9f,49.9f,74.9f}[hits.Length]);site.Signal=Math.Clamp(signal,0,100);if(site.Signal>=99.99f)site.Signal=100;site.ResultShape=hits.Length==1?"Sphere":hits.Length==2?"Circle":hits.Length==3?"Two points":"Point";float range=hits[0].Probe.Range;site.DeviationAU=(1-site.Signal/100)*range*.5f*job.DeviationMultiplier;float phase=StableProbeHash(site.Id)*.013f+ProbeScanPass*1.7f;var deviation=new Vector3(MathF.Sin(phase),MathF.Cos(phase*.7f)*.5f,MathF.Cos(phase))*site.DeviationAU;var estimate=target+deviation;site.EstimateX=estimate.X;site.EstimateY=estimate.Y;site.EstimateZ=estimate.Z;if(site.Id=="umbra:signal"&&site.Signal==100)SignalResolved=true;}ProbeStatus="Analysis complete. Position, narrow and analyze again.";Say(ProbeStatus);}
 public bool ProbeContactAlive(UtilitySite site){if(site.TargetId.Length==0)return true;var t=ProbeContact(site);return t?.Alive==true&&t.Profile?.Special.Any(s=>s.Active&&s.Definition?.Cloak==true)!=true;}
 public SpaceTarget? ProbeContact(UtilitySite s)=>s.ContactGrid.Length==0?Targets.FirstOrDefault(t=>t.Id==s.TargetId):SolarGrids.GetValueOrDefault(s.ContactGrid)?.Targets.FirstOrDefault(t=>t.Id==s.TargetId);
 float ProbeContactDifficulty(UtilitySite site){var t=ProbeContact(site);if(t==null)return 1000;float signature=(float)(t.Profile?.Stat("signatureRadius")??t.Signature);return Math.Clamp(40/Math.Max(1,signature)*20,4,1000);}
 public static float ProbeGeometry(Vector3[] points,float range){if(points.Length==0)return 0;if(points.Length<4)return points.Length/4f;float best=0;for(int i=0;i<points.Length-3;i++)for(int j=i+1;j<points.Length-2;j++)for(int k=j+1;k<points.Length-1;k++)for(int l=k+1;l<points.Length;l++)best=Math.Max(best,Math.Abs(Vector3.Dot(points[j]-points[i],Vector3.Cross(points[k]-points[i],points[l]-points[i]))));return Math.Clamp(best/Math.Max(.0000001f,range*range*range*.12f),.03f,1);}
 static int StableProbeHash(string s){int n=17;foreach(char c in s)n=unchecked(n*31+c);return n&0x7fffffff;}
 public static string ProbeSignatureCode(UtilitySite site){int n=StableProbeHash(site.Id);return site.Id=="umbra:signal"?"JOY-001":$"{(char)('A'+n%26)}{(char)('A'+n/26%26)}{(char)('A'+n/676%26)}-{n%1000:000}";}
 public string ProbeResultGroup(UtilitySite s)=>s.Anomaly?"Cosmic Anomaly":s.Signal<25?"Cosmic Signature":s.Kind is "Ship" or "Drone" or "Structure"?s.Kind:s.Kind+" Site";
 public string ProbeResultName(UtilitySite s)=>s.Signal>=75||s.Anomaly?s.Name:"Unknown";
 public bool ProbeWarpable(UtilitySite s)=>s.System==SystemId&&s.Signal>=100&&(!s.Id.StartsWith("wf:")||Exploration.Connections.Any(h=>"wf:"+h.Id==s.Id&&ConnectionAvailableO(h)))&&SiteAvailableN(s)&&ProbeContactAlive(s);
 public bool BookmarkProbeResult(string id){var s=UtilitySites.FirstOrDefault(s=>s.Id==id);if(s==null||!ProbeWarpable(s))return false;Bookmarks.Add(new("bookmark:"+Guid.NewGuid().ToString("N"),SystemId,s.Name,new(s.X*SolarCatalog.AU,s.Y*SolarCatalog.AU,s.Z*SolarCatalog.AU)));return true;}
}
